        { var matrix = value.Animation; if (BitConverter.IsLittleEndian) w.Write(MemoryMarshal.AsBytes(MemoryMarshal.CreateReadOnlySpan(ref matrix, 1))); else for (int r = 0; r < 4; r++) for (int c = 0; c < 4; c++) w.Write(matrix[r, c]); }
        w.Write(value.RoomPartId);
        w.Write(value.RoomPartActive);
    }
    internal static void Write(BinaryWriter w, global::MphRead.Mesh value)
    {
