        w.Write(value.Ambient.Red); w.Write(value.Ambient.Green); w.Write(value.Ambient.Blue);
        w.Write(value.CurrentDiffuse.X); w.Write(value.CurrentDiffuse.Y); w.Write(value.CurrentDiffuse.Z);
        w.Write(value.CurrentAmbient.X); w.Write(value.CurrentAmbient.Y); w.Write(value.CurrentAmbient.Z);
